package com.delivery.platform.payments.application;
import com.delivery.platform.common.*;import com.delivery.platform.identity.security.IdentityPrincipal;import com.delivery.platform.payments.domain.PaymentTypes.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.Instant;import java.util.*;
@Service public class PaymentService{private final JdbcClient db;private final PaymentProvider provider;public PaymentService(JdbcClient db,List<PaymentProvider> providers){this.db=db;this.provider=providers.stream().filter(x->x.code().equals("SIMULATED")).findFirst().orElseThrow();}public record Payment(UUID id,UUID orderId,UUID customerId,UUID merchantId,Method paymentMethod,String provider,Status status,String currency,BigDecimal amount,BigDecimal authorizedAmount,BigDecimal capturedAmount,BigDecimal refundedAmount,String providerPaymentId,String failureCode,String failureMessage,Instant createdAt){}public record Transaction(UUID id,String transactionType,String providerTransactionId,BigDecimal amount,String currency,String status,Instant createdAt){}
 @Transactional public Payment create(IdentityPrincipal p,UUID orderId,Method method,String reference,String key){requiredKey(key);var order=db.sql("select id,customer_id,merchant_id,total,currency,status from orders where id=:o and tenant_id=:t and customer_id=:u").param("o",orderId).param("t",p.tenantId()).param("u",p.userId()).query((r,n)->new Object[]{r.getObject("customer_id",UUID.class),r.getObject("merchant_id",UUID.class),r.getBigDecimal("total"),r.getString("currency"),r.getString("status")}).optional().orElseThrow(()->error(HttpStatus.NOT_FOUND,"ORDER_NOT_FOUND","Pedido no encontrado"));Optional<UUID> existing=db.sql("select id from payments where tenant_id=:t and idempotency_key=:k").param("t",p.tenantId()).param("k",key).query(UUID.class).optional();if(existing.isPresent())return one(p,existing.get());UUID id=UUID.randomUUID();String providerCode=method==Method.CASH_ON_DELIVERY?"CASH":"SIMULATED";db.sql("insert into payments(id,tenant_id,order_id,customer_id,merchant_id,payment_method,provider,status,currency,amount,idempotency_key,provider_reference) values(:i,:t,:o,:u,:m,:x,:p,'PENDING',:c,:a,:k,:r)").param("i",id).param("t",p.tenantId()).param("o",orderId).param("u",p.userId()).param("m",order[1]).param("x",method.name()).param("p",providerCode).param("c",order[3]).param("a",order[2]).param("k",key).param("r",reference).update();audit(p,"PAYMENT_CREATED",id);if(method!=Method.CASH_ON_DELIVERY)return confirm(p,id);return one(p,id);}
 @Transactional public Payment confirm(IdentityPrincipal p,UUID id){Payment pay=one(p,id);if(pay.status()==Status.PAID||pay.status()==Status.AUTHORIZED)return pay;if(pay.status()!=Status.PENDING&&pay.status()!=Status.FAILED)throw error(HttpStatus.CONFLICT,"PAYMENT_ALREADY_PROCESSED","El pago ya fue procesado");int attempt=db.sql("select count(*)+1 from payment_attempts where payment_id=:p").param("p",id).query(Integer.class).single();String ref=db.sql("select provider_reference from payments where id=:p").param("p",id).query(String.class).optional().orElse("");db.sql("insert into payment_attempts(id,tenant_id,payment_id,attempt_number,request_reference,provider,status,amount) values(gen_random_uuid(),:t,:p,:n,:r,'SIMULATED','PROCESSING',:a)").param("t",p.tenantId()).param("p",id).param("n",attempt).param("r",UUID.randomUUID().toString()).param("a",pay.amount()).update();var result=provider.process(ref,pay.amount(),pay.currency());String status=result.approved()?"PAID":"FAILED",type=result.approved()?"SALE":"FAILED";db.sql("update payments set status=:s,captured_amount=:a,provider_payment_id=:x,failure_code=:c,failure_message=:m,captured_at=case when :ok then now() end,updated_at=now() where id=:p").param("s",status).param("a",result.approved()?pay.amount():BigDecimal.ZERO).param("x",result.providerPaymentId()).param("c",result.failureCode()).param("m",result.failureMessage()).param("ok",result.approved()).param("p",id).update();db.sql("update payment_attempts set status=:s,failure_code=:c,failure_message=:m,completed_at=now() where payment_id=:p and attempt_number=:n").param("s",status).param("c",result.failureCode()).param("m",result.failureMessage()).param("p",id).param("n",attempt).update();transaction(p,id,type,result.transactionId(),pay.amount(),pay.currency(),status);if(result.approved()){db.sql("update orders set payment_status='PAID',status=case when status='PENDING' then 'CONFIRMED' else status end,updated_at=now() where id=:o and tenant_id=:t").param("o",pay.orderId()).param("t",p.tenantId()).update();audit(p,"PAYMENT_CONFIRMED",id);}else audit(p,"PAYMENT_FAILED",id);return one(p,id);}
 @Transactional public Payment cancel(IdentityPrincipal p,UUID id){Payment pay=one(p,id);if(pay.status()==Status.PAID||pay.status()==Status.REFUNDED)throw error(HttpStatus.CONFLICT,"PAYMENT_INVALID_STATE","Un pago confirmado no puede cancelarse");db.sql("update payments set status='CANCELLED',cancelled_at=now(),updated_at=now() where id=:p").param("p",id).update();transaction(p,id,"VOID",null,pay.amount(),pay.currency(),"CANCELLED");audit(p,"PAYMENT_CANCELLED",id);return one(p,id);}
 @Transactional public Payment refund(IdentityPrincipal p,UUID id,BigDecimal amount,String reason,String key){requiredKey(key);Payment pay=one(p,id);if(pay.status()!=Status.PAID&&pay.status()!=Status.PARTIALLY_REFUNDED)throw error(HttpStatus.CONFLICT,"PAYMENT_INVALID_STATE","El pago no admite reembolso");BigDecimal available=pay.capturedAmount().subtract(pay.refundedAmount());if(amount.signum()<=0||amount.compareTo(available)>0)throw error(HttpStatus.CONFLICT,"REFUND_AMOUNT_EXCEEDED","El monto supera el saldo reembolsable");if(db.sql("select count(*) from payment_refunds where tenant_id=:t and idempotency_key=:k").param("t",p.tenantId()).param("k",key).query(Integer.class).single()>0)return pay;UUID refund=UUID.randomUUID();BigDecimal total=pay.refundedAmount().add(amount);String status=total.compareTo(pay.capturedAmount())==0?"REFUNDED":"PARTIALLY_REFUNDED";db.sql("insert into payment_refunds(id,tenant_id,payment_id,order_id,amount,reason,status,provider_refund_id,requested_by,idempotency_key,processed_at) values(:i,:t,:p,:o,:a,:r,'COMPLETED',:x,:u,:k,now())").param("i",refund).param("t",p.tenantId()).param("p",id).param("o",pay.orderId()).param("a",amount).param("r",reason).param("x","ref_"+UUID.randomUUID()).param("u",p.userId()).param("k",key).update();db.sql("update payments set refunded_amount=:a,status=:s,updated_at=now() where id=:p").param("a",total).param("s",status).param("p",id).update();transaction(p,id,"REFUND",refund.toString(),amount,pay.currency(),"COMPLETED");audit(p,"PAYMENT_REFUNDED",id);return one(p,id);}
 public Payment one(IdentityPrincipal p,UUID id){return db.sql("select * from payments where id=:i and tenant_id=:t and (customer_id=:u or :admin)").param("i",id).param("t",p.tenantId()).param("u",p.userId()).param("admin",p.permissions().contains("PAYMENT_ADMIN")).query((r,n)->map(r)).optional().orElseThrow(()->error(HttpStatus.NOT_FOUND,"PAYMENT_NOT_FOUND","Pago no encontrado"));}public List<Payment> byOrder(IdentityPrincipal p,UUID order){return db.sql("select * from payments where tenant_id=:t and order_id=:o and (customer_id=:u or :admin) order by created_at desc").param("t",p.tenantId()).param("o",order).param("u",p.userId()).param("admin",p.permissions().contains("PAYMENT_ADMIN")).query((r,n)->map(r)).list();}public PageResponse<Payment> list(IdentityPrincipal p,String status,String method,int page,int size){int z=Math.min(Math.max(size,1),100),pg=Math.max(page,0);String w=" from payments where tenant_id=:t and (cast(:s as varchar) is null or status=:s) and (cast(:m as varchar) is null or payment_method=:m)";var rows=db.sql("select *"+w+" order by created_at desc limit :z offset :o").param("t",p.tenantId()).param("s",status).param("m",method).param("z",z).param("o",pg*z).query((r,n)->map(r)).list();long count=db.sql("select count(*)"+w).param("t",p.tenantId()).param("s",status).param("m",method).query(Long.class).single();return PageResponse.of(rows,pg,z,count);}public List<Transaction> transactions(IdentityPrincipal p,UUID id){one(p,id);return db.sql("select * from payment_transactions where tenant_id=:t and payment_id=:p order by created_at").param("t",p.tenantId()).param("p",id).query((r,n)->new Transaction(r.getObject("id",UUID.class),r.getString("transaction_type"),r.getString("provider_transaction_id"),r.getBigDecimal("amount"),r.getString("currency"),r.getString("status"),r.getTimestamp("created_at").toInstant())).list();}
 private Payment map(java.sql.ResultSet r)throws java.sql.SQLException{return new Payment(r.getObject("id",UUID.class),r.getObject("order_id",UUID.class),r.getObject("customer_id",UUID.class),r.getObject("merchant_id",UUID.class),Method.valueOf(r.getString("payment_method")),r.getString("provider"),Status.valueOf(r.getString("status")),r.getString("currency"),r.getBigDecimal("amount"),r.getBigDecimal("authorized_amount"),r.getBigDecimal("captured_amount"),r.getBigDecimal("refunded_amount"),r.getString("provider_payment_id"),r.getString("failure_code"),r.getString("failure_message"),r.getTimestamp("created_at").toInstant());}private void transaction(IdentityPrincipal p,UUID id,String type,String providerId,BigDecimal amount,String currency,String status){db.sql("insert into payment_transactions(id,tenant_id,payment_id,transaction_type,provider_transaction_id,amount,currency,status) values(gen_random_uuid(),:t,:p,:x,:i,:a,:c,:s)").param("t",p.tenantId()).param("p",id).param("x",type).param("i",providerId).param("a",amount).param("c",currency).param("s",status).update();}private void audit(IdentityPrincipal p,String action,UUID id){db.sql("insert into audit_logs(tenant_id,user_id,action,entity_type,entity_id) values(:t,:u,:a,'PAYMENT',:i)").param("t",p.tenantId()).param("u",p.userId()).param("a",action).param("i",id).update();}private void requiredKey(String k){if(k==null||k.isBlank())throw error(HttpStatus.BAD_REQUEST,"IDEMPOTENCY_KEY_REQUIRED","Envía el encabezado Idempotency-Key");}private ApiException error(HttpStatus s,String c,String m){return new ApiException(s,c,m);}}
